const fs=require('fs');const puppeteer=require('puppeteer-core');const vps=[{name:'768x1024',width:768,height:1024},{name:'390x844',width:390,height:844},{name:'360x800',width:360,height:800}];(async()=>{const b=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage']});const out={cases:{},failures:[]};fs.mkdirSync('gate-a-postfix/nojs',{recursive:true});for(const vp of vps){const p=await b.newPage();await p.setJavaScriptEnabled(false);await p.setViewport({width:vp.width,height:vp.height});await p.goto('http://127.0.0.1:8000/index.html',{waitUntil:'domcontentloaded'});const d=await p.evaluate(()=>{const n=document.querySelector('#primary-nav'),t=document.querySelector('.menu-toggle'),links=[...n.querySelectorAll('a[href]')];const ns=getComputedStyle(n),ts=getComputedStyle(t);return{htmlClass:document.documentElement.className,toggleDisplay:ts.display,navPosition:ns.position,navDisplay:ns.display,navVisibility:ns.visibility,links:links.map(x=>x.textContent.trim()),horizontalOverflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+2}});out.cases[vp.name]=d;if(d.htmlClass.includes('js')||d.toggleDisplay!=='none'||d.navPosition!=='static'||d.navVisibility==='hidden'||d.links.length!==6||d.horizontalOverflow)out.failures.push({viewport:vp.name,data:d});await p.screenshot({path:`gate-a-postfix/nojs/nojs-${vp.name}.png`,fullPage:false});await p.close()}fs.writeFileSync('gate-a-postfix/nojs/nojs-report.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));await b.close();if(out.failures.length)process.exit(2)})().catch(e=>{console.error(e);process.exit(1)});
